"""Self-contained exact-value explorer and certified-rank comparison."""
import json
from pathlib import Path
OUT=Path('results/marked-frontier/2026-11-06');data=json.loads((OUT/'explorer-data.json').read_text())
page=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{--foreground:#e7e9ee;--muted-foreground:#a5afbd;--card:#20252e;--border:#46505d;--chart-1:#a6baff;--chart-2:#505c6d;--radius:10px;--font-sans:system-ui,sans-serif;--font-mono:ui-monospace,monospace}
body{margin:0;color:var(--foreground);font:14px/1.5 var(--font-sans)}p{margin:0 0 12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}label,small,.muted{color:var(--muted-foreground)}label{font-size:12px}select{box-sizing:border-box;width:100%;background:var(--card);color:var(--foreground);border:1px solid var(--border);border-radius:6px;padding:7px;margin:4px 0 12px;font:inherit}.card{background:var(--card);border-radius:var(--radius);padding:16px;margin:4px 0 16px}.value{font:16px var(--font-mono);overflow-wrap:anywhere;margin:5px 0 10px}h3{font-size:15px;margin:12px 0 6px}svg{width:100%;height:270px;display:block}svg text{font:12px var(--font-sans);fill:var(--foreground)}.legend{font-size:12px}.dot{display:inline-block;width:9px;height:9px;margin-right:5px;border-radius:2px}@media(max-width:450px){.results{grid-template-columns:1fr}}
</style></head><body><p><strong>54 presentations · genera 2 and 3 · up to five marks</strong><br><span class="muted">Degree ≤ 2 · exact fractions · certified Chow relations in codimensions 0–2</span></p>
<div class="grid"><label>Genus<select id="g"><option>2</option><option>3</option></select></label><label>Curve class<select id="beta"></select></label></div>
<label>Presentation<select id="target"></select></label><div class="three"><label>Total marks<select id="n"></select></label><label>ψ insertions<select id="psi"></select></label><label>H insertions<select id="H"></select></label></div>
<div class="card"><p id="profile"></p><div class="grid results"><div><small>Ordinary compact GW number</small><div class="value" id="N"></div></div><div><small>Ambient twisted coefficient</small><div class="value" id="Z"></div></div></div><small>CJR infinity aggregate</small><div class="value" id="B"></div><div class="muted" id="details"></div></div>
<h3>Codimension-two relation spans</h3><div class="legend"><span class="dot" style="background:var(--chart-1)"></span>Found, including declared functorial consequences &nbsp;<span class="dot" style="background:var(--chart-2)"></span>Pixton</div><svg id="chart" viewBox="0 0 650 270" role="img" aria-label="Found and Pixton relation ranks, zero to five marks"></svg>
<p class="muted" id="ceiling"></p><div class="card"><strong>Memory constrained concurrency</strong><p class="muted" id="memory"></p><small>Host counters include other applications. Worker RSS is not total physical use. Large four- and five-mark batches were separated to preserve headroom.</small></div>
<p class="muted" style="font-size:12px">The flag CY3 Fl(1,2;4)[(1,1),(1,2)] has 33 and 88 primitive fiber lines, 5 fiber conics, and 634 mixed-degree rational curves in the bounded window. Unknown compact inputs elsewhere remain unknown.</p>
<script>
const D=__DATA__,el=id=>document.getElementById(id);let active=[];
function gcd(a,b){a=a<0n?-a:a;while(b)[a,b]=[b,a%b];return a}
function fraction(s){if(s===null)return null;let a=s.split('/');return[BigInt(a[0]),BigInt(a[1]||1)]}
function fmt(q){if(q===null)return'unknown';let[a,b]=q,c=gcd(a,b);a/=c;b/=c;return b===1n?String(a):`${a}/${b}`}
function mul(q,m){if(!m)return[0n,1n];return q===null?null:[q[0]*BigInt(m),q[1]]}
function minus(a,b){return a===null||b===null?null:[a[0]*b[1]-b[0]*a[1],a[1]*b[1]]}
function choices(id,max,keep){el(id).replaceChildren();for(let i=0;i<=max;i++)el(id).add(new Option(i,i));el(id).value=Math.min(keep||0,max)}
function values(){let r=active[+el('target').value].rows[+el('beta').value],g=+el('g').value,n=+el('n').value,k=+el('psi').value,h=+el('H').value,u=n-k-h,m=u?0:r.H_degree**h;for(let j=0;j<k;j++)m*=2*g-2+h+j;let z=mul(fraction(r.twisted_unmarked),m),N=mul(fraction(r.ordinary_unmarked),m),power=r.alpha+k+h-(3*g-3+n),B=power<0?mul(z,-1):power===0?minus(mul(N,r.sign),z):null;el('Z').textContent=fmt(z);el('N').textContent=fmt(N);el('B').textContent=fmt(B);el('profile').textContent=`${k} × τ₁(1), ${h} × H, ${u} × 1`;el('details').textContent=`Any labeling has this numerical value · multiplier ${m} · H·β = ${r.H_degree} · t power ${power}`}
function marks(){choices('psi',+el('n').value,+el('psi').value);choices('H',+el('n').value-(+el('psi').value),+el('H').value);values()}
function beta(){let old=el('beta').selectedOptions[0]?.textContent;el('beta').replaceChildren();active[+el('target').value].rows.forEach((r,i)=>{let label='('+r.beta.join(', ')+')';el('beta').add(new Option(label,i));if(label===old)el('beta').value=i});values()}
function genus(){let old=active[+el('target').value]?.id;active=D.records.filter(x=>x.genus===+el('g').value);el('target').replaceChildren();active.forEach((x,i)=>el('target').add(new Option(x.id+' · '+x.name,i)));el('target').value=Math.max(0,active.findIndex(x=>x.id===(old||'PF4')));beta();chart()}
function chart(){let g=+el('g').value,rows=D.spaces.filter(s=>s.g===g&&s.r===2),max=Math.max(...rows.map(x=>x.pixton));el('chart').innerHTML=rows.map((x,i)=>{let y=8+43*i,w=410,left=72;return`<text x="0" y="${y+19}">${x.n} marks</text><rect x="${left}" y="${y}" width="${w*x.pixton/max}" height="27" rx="3" fill="var(--chart-2)"/><rect x="${left}" y="${y+5}" width="${w*x.found/max}" height="17" rx="2" fill="var(--chart-1)"/><text x="${left+w*x.pixton/max+10}" y="${y+19}">${x.found} / ${x.pixton}</text>`}).join('');el('ceiling').textContent=g===3?'At five marks, all non-unit coefficients in this genus-three window vanish by dimension; unit profiles are reconstructed with boundary corrections.':'Genus-two non-unit coefficients can survive beyond five marks. This completed pass stops at five after the flag curve counts and certified spans were obtained.'}
choices('n',5,5);choices('psi',5,5);choices('H',0,0);el('g').onchange=genus;el('target').onchange=beta;el('beta').onchange=values;el('n').onchange=marks;el('psi').onchange=()=>{choices('H',+el('n').value-(+el('psi').value),+el('H').value);values()};el('H').onchange=values;genus();el('beta').value=active[+el('target').value].rows.findIndex(x=>x.beta.join(',')==='1,0');values();let m=D.memory;el('memory').textContent=`${m.physical_gib.toFixed(0)} GiB physical RAM · ${m.peak_worker_gib.toFixed(2)} GiB largest worker RSS · ${m.minimum_guest_available_gib.toFixed(2)} GiB minimum guest available memory · ${m.guest_oom_kill_change} new guest OOM kills.`;
</script></body></html>'''
page=page.replace('__DATA__',json.dumps(data,separators=(',',':')))
(OUT/'explorer.html').write_text(page);print(OUT/'explorer.html')
